use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{collections::{BTreeMap,BTreeSet},fs,io::Read,path::{Path,PathBuf}};
const R:&str="/home/ubuntu/src/zopro-perf-work/inverse-hint-alias176";fn r(s:impl AsRef<Path>)->PathBuf{Path::new(R).join(s)}fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{let mut f=fs::File::open(p).unwrap();let mut h=Sha256::new();let mut b=[0;65536];loop{let n=f.read(&mut b).unwrap();if n==0{break}h.update(&b[..n]);}format!("{:x}",h.finalize())}
fn near(a:f64,b:f64){assert!((a-b).abs()<=1e-12*a.abs().max(b.abs()).max(1.),"{a}!={b}");}
fn middle(v:&[f64])->f64{let mut v=v.to_vec();v.sort_by(|a,b|a.partial_cmp(b).unwrap());v[v.len()/2]}
fn check_interval(values:&[f64],v:&Value){assert_eq!(values.len(),15);let mut s=values.to_vec();s.sort_by(|a,b|a.partial_cmp(b).unwrap());for(k,x)in[("median",s[7]),("low",s[3]),("high",s[11])]{near(x,v[k].as_f64().unwrap());}assert_eq!(v["wins"].as_u64().unwrap()as usize,values.iter().filter(|&&x|x<1.).count());for(a,b)in values.iter().zip(v["ratios"].as_array().unwrap()){near(*a,b.as_f64().unwrap());}}
fn main(){
 let mut pin_count=0;for file in["qualification-pins.json","qualification-v2-pins.json","build-pins.json","pins.json"]{for(p,h)in read(r(file)).as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap());pin_count+=1;}}
 let mut command_count=0;for(folder,count)in[("qualification-v2",2),("build",4),("runs",439)]{
  let result=read(r(format!("{folder}/result.json")));assert_eq!(result["status"],"complete");let steps=result["steps"].as_array().unwrap();assert_eq!(steps.len(),count);
  for name in steps{let p=r(format!("{folder}/{}",name.as_str().unwrap()));let e=read(p.join("exit.json"));assert_eq!(e["success"],true);assert_eq!(e["returncode"],0);for stream in["stdout","stderr"]{assert_eq!(hash(p.join(format!("{stream}.log"))),e[format!("{stream}_sha256")]);}
   if p.join("artifacts.json").exists(){let a=read(p.join("artifacts.json"));for(p,h)in a["input_pins"].as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap());}assert_eq!(hash(a["binary"].as_str().unwrap()),a["binary_sha256"]);}
   command_count+=1;
  }
 }
 for(p,n)in[("qualification-v2/core/tests.json",128),("qualification-v2/prover-ON/tests.json",2),("build/cubic-ON/tests.json",6)]{let v=read(r(p));assert_eq!(v["unfiltered"],true);assert_eq!(v["passed_tests"].as_array().unwrap().len(),n);}
 let old=read(r("source-pins.json"));let new=read(r("source-v2-pins.json"));assert_eq!(old.as_object().unwrap().len(),177);assert_eq!(new.as_object().unwrap().len(),177);let mut changed=0;
 for(p,h)in old.as_object().unwrap(){let next=p.replacen("/source/","/source-v2/",1);assert_eq!(hash(p),h.as_str().unwrap());assert_eq!(hash(&next),new[&next]);if hash(p)!=hash(&next){assert!(p.ends_with("solver/inverse_aliases.rs"));changed+=1;}}
 assert_eq!(changed,1);assert_eq!(read(r("qualification/core/exit.json"))["returncode"],101);
 let a=read(r("analysis.json"));let rows=read(r("rows.json"));let jobs=read(r("jobs.json"));let mut fresh=BTreeSet::new();let mut values=BTreeMap::new();let mut sdk=0;
 for j in jobs.as_array().unwrap(){let name=j["name"].as_str().unwrap();let text=fs::read_to_string(r(format!("runs/{name}/stdout.log"))).unwrap();let s=text.lines().filter_map(|l|l.strip_prefix("SAMPLE ")).map(|l|serde_json::from_str::<Value>(l).unwrap()).collect::<Vec<_>>();let n=j["rounds"].as_u64().unwrap();assert_eq!(s.len(),n as usize);sdk+=n+3;
  let samples=s.iter().enumerate().map(|(i,v)|{assert_eq!(v["round"],i);v["ms"].as_f64().unwrap()}).collect::<Vec<_>>();let v=middle(&samples);let row=rows.as_array().unwrap().iter().find(|r|r["name"]==name).unwrap();near(v,row["median_ms"].as_f64().unwrap());
  if j["panel"]=="latency"{assert!(values.insert((j["case"]["name"].as_str().unwrap().to_string(),j["variant"].as_str().unwrap().to_string(),j["block"].as_u64().unwrap()),v).is_none());}
  if j["variant"]!="accepted"{let lines=text.lines().filter_map(|l|l.strip_prefix("INVERSE_ALIAS ")).collect::<Vec<_>>();assert_eq!(lines.len(),1);let c:Value=serde_json::from_str(lines[0]).unwrap();let c=&c["layout_and_counts"];assert_eq!(c[0],72);assert_eq!(c[1],56);let expected=if j["variant"]=="OFF"{0}else if j["case"]["shape"]=="1x2"{49}else{72};assert_eq!(c[2],expected);let peak=if expected==0{0}else if expected==49{36640}else{64132};assert_eq!(c[3],peak);}
  let dir=Path::new(j["directory"].as_str().unwrap());let proof=hash(dir.join("0.proof"));assert!(fresh.insert(proof.clone()));assert_eq!(hash(dir.join("0.public")),j["case"]["public_sha256"]);let v=fs::read_to_string(r(format!("runs/verify-{name}/stdout.log"))).unwrap();assert!(v.contains(&format!("proof_sha256={proof}")));assert!(v.contains(&format!("image_sha256={}",j["case"]["image_sha256"].as_str().unwrap())));
 }
 assert_eq!(sdk,21816);assert_eq!(fresh.len(),204);let prior:BTreeSet<String>=serde_json::from_value(read(r("prior-proof-sha256.json"))).unwrap();assert!(fresh.is_disjoint(&prior));let final_ledger:BTreeSet<String>=serde_json::from_value(read(r("proof-sha256-after.json"))).unwrap();assert_eq!(prior.union(&fresh).cloned().collect::<BTreeSet<_>>(),final_ledger);assert_eq!(final_ledger.len(),29051);
 let cases=read(r("cases.json"));let mut failed=vec![];
 for c in cases.as_array().unwrap(){let name=c["name"].as_str().unwrap();for arm in["accepted","OFF","ON"]{let vs=(0..15).map(|b|values[&(name.into(),arm.into(),b)]).collect::<Vec<_>>();near(middle(&vs),a["cells"][name][arm]["median_ms"].as_f64().unwrap());}
  for(x,y)in[("OFF","accepted"),("ON","accepted"),("ON","OFF")]{let vs=(0..15).map(|b|values[&(name.into(),x.into(),b)]/values[&(name.into(),y.into(),b)]).collect::<Vec<_>>();let key=format!("{name}/{x}/{y}");let s=&a["pairs"][&key];check_interval(&vs,s);let lo=s["low"].as_f64().unwrap();let hi=s["high"].as_f64().unwrap();if x=="OFF" {if lo<1./1.03||hi>1.03{failed.push(format!("{key}/calibration"));}}else{if hi>1.03{failed.push(format!("{key}/nonregression"));}if c["workers"]==32&&hi>1.{failed.push(format!("{key}/32-worker-upper-bound"));}}
  }
 }
 for ctrl in["accepted","OFF"]{let vs=(0..15).map(|b|{let product=cases.as_array().unwrap().iter().map(|c|{let n=c["name"].as_str().unwrap();values[&(n.into(),"ON".into(),b)]/values[&(n.into(),ctrl.into(),b)]}).product::<f64>();product.powf(0.25)}).collect::<Vec<_>>();let s=&a["aggregates"][ctrl]["statistics"];check_interval(&vs,s);let pass=s["high"].as_f64().unwrap()<1.&&s["wins"].as_u64().unwrap()>=10;assert_eq!(a["aggregates"][ctrl]["passed"],pass);if !pass{failed.push(format!("four-contexts/ON/{ctrl}/gain"));}}
 let declared=a["failed_checks"].as_array().unwrap().iter().map(|v|v.as_str().unwrap().to_string()).collect::<BTreeSet<_>>();assert_eq!(failed.iter().cloned().collect::<BTreeSet<_>>(),declared);assert_eq!(a["gate_passed"],failed.is_empty());
 let mut all_samples=0;for(n,p)in a["profiles"].as_object().unwrap(){let bins=read(r("profile-symbols.json"))[n].as_array().unwrap().clone();let samples=bins.iter().map(|v|v["samples"].as_u64().unwrap()).sum::<u64>();assert_eq!(p["samples"],samples);assert_eq!(p["period"],samples*16000000);all_samples+=samples;assert_eq!(read(r(format!("runs/loss-{n}/stdout.log")))["zero_lost"],true);}
 fs::write(r("review.json"),serde_json::to_vec_pretty(&json!({"passed":true,"pin_entries_checked":pin_count,"successful_commands_checked":command_count,"initial_failed_core_preserved":true,"source_v2_only_child_layout_repair":true,"SDK_requests":sdk,"fresh_Gnark_exports":fresh.len(),"proof_ledger":final_ledger.len(),"independent_latency_and_gate_reconstruction":true,"profile_sample_conservation":all_samples,"failed_checks":failed,"production_changed":false,"adopted":false})).unwrap()).unwrap();println!("ReviewPASS:{pin_count}pinentries/{command_count}successfulcommands/rawSDKsamples/gates/204proofs/ledger29051/{all_samples}profilesamples;failedsource preserved");
}
